/* eslint-disable no-console */
import { Howl, SoundSpriteDefinitions } from 'howler';

import { IHowlSoundAssetConfig } from '../types';

/* eslint @typescript-eslint/ban-ts-comment: 0 */
export class Sound extends Howl {
    private config: IHowlSoundAssetConfig;

    public get name() {
        return this.config.name;
    }

    public get sprites() {
        return this.config.sprite ?? {} as SoundSpriteDefinitions;
    }

    public get isLoaded() {
        return this.state() === 'loaded';
    }

    constructor(config: IHowlSoundAssetConfig) {
        config = Object.assign(config, {
            preload: false
        });
        super(config);
        this.config = config;
        // this.DEBUG_LISTENERS();
    }

    protected DEBUG_LISTENERS() {
        this.on('load', (...args) => {
            console.log(`Sound load: ${this.name}: `, ...args);
        });
        this.on('loaderror', (...args) => {
            console.log(`Sound load error: ${this.name}: `, ...args);
        });
        this.on('playerror', (...args) => {
            console.log(`Sound play error: ${this.name}: `, ...args);
        });
        this.on('volume', (...args) => {
            console.log(`Sound volume change: ${this.name}: `, ...args);
        });
        this.on('stop', (...args) => {
            console.log(`Sound stop: ${this.name}: `, ...args);
        });
        this.on('seek', (...args) => {
            console.log(`Sound seek: ${this.name}: `, ...args);
        });
        this.on('rate', (...args) => {
            console.log(`Sound rate change: ${this.name}: `, ...args);
        });
        this.on('play', (...args) => {
            console.log(`Sound play: ${this.name}: `, ...args);
        });
        this.on('pause', (...args) => {
            console.log(`Sound pause: ${this.name}: `, ...args);
        });
        this.on('mute', (...args) => {
            console.log(`Sound mute: ${this.name}: `, ...args);
        });
        this.on('fade', (...args) => {
            console.log(`Sound fade: ${this.name}: `, ...args);
        });
        this.on('end', (...args) => {
            console.log(`Sound end: ${this.name}: `, ...args);
        });
        this.on('unlock', (...args) => {
            console.log(`Sound unlock: ${this.name}: `, ...args);
        });
    }

    // @ts-ignore
    public load() {
        return new Promise<void>((resolve, reject) => {
            this.once('load', () => resolve());
            this.once('loaderror', (soundId: number, error: any) => reject(new Error(`Failed to load SoundSprite "${this.name}" using "${this.config.src}": ${error}`)));
            super.load();
        });
    }
}